@Service
public class OrderService {
    // Use CompletableFuture for non-blocking I/O to handle high concurrency
    public CompletableFuture<OrderResponse> processOrderAsync(OrderRequest request) {
        return CompletableFuture.supplyAsync(() -> {
            // Offload to thread pool to avoid blocking the main request thread
            return orderRepository.save(request);
        }, customExecutor);
    }
}
